<!DOCTYPE html>
<html lang="fa" dir="rtl">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>پلن‌ها | Hale</title>@vite(['resources/css/app.css','resources/js/app.js'])</head>
<body class="dashboard-page"><div class="app-shell"><header class="topbar"><a class="brand" href="/">H<span>•</span>le</a><div class="topbar-actions"><a class="text-button" href="/dashboard">داشبورد</a></div></header><main class="pricing-page"><p class="eyebrow">PRICING / HALE</p><div class="pricing-heading"><h1>پلن مناسب<br><em>رشد تو.</em></h1><p>اعتبار بیشتر، فضای بیشتر برای ساختن.</p></div><div class="pricing-grid" data-pricing-grid><p class="empty-state">در حال بارگذاری پلن‌ها...</p></div><section class="payment-history"><div class="section-heading"><h2>تاریخچه پرداخت</h2></div><div class="payment-list" data-payment-list><p class="empty-state">در حال بارگذاری...</p></div></section><p class="form-message" data-pricing-message role="alert"></p></main></div><script>const pricingToken = localStorage.getItem('hale_token'); const pricingGrid = document.querySelector('[data-pricing-grid]'); const pricingMessage = document.querySelector('[data-pricing-message]'); const paymentList = document.querySelector('[data-payment-list]'); const paymentStatus = new URLSearchParams(window.location.search).get('payment'); if (paymentStatus) { pricingMessage.className = paymentStatus === 'paid' ? 'form-message success-message' : 'form-message error-message'; pricingMessage.textContent = paymentStatus === 'paid' ? 'پرداخت موفق بود؛ پلن شما فعال شد.' : 'پرداخت ناموفق بود. دوباره تلاش کنید.'; if (paymentStatus === 'paid' && pricingToken) { fetch('/api/user/profile', { headers: { Accept: 'application/json', Authorization: `Bearer ${pricingToken}` } }).then((res) => res.json()).then((result) => { if (result.data) localStorage.setItem('hale_user', JSON.stringify(result.data)); }).catch(() => {}); } } const money = (value) => new Intl.NumberFormat('fa-IR').format(value / 10) + ' تومان'; const paymentLabels = { pending: 'در انتظار پرداخت', paid: 'پرداخت موفق', failed: 'ناموفق' }; const loadPayments = async () => { if (!pricingToken) { paymentList.innerHTML = '<p class="empty-state">برای مشاهده تاریخچه وارد شوید.</p>'; return; } const response = await fetch('/api/payments?per_page=10', { headers: { Accept: 'application/json', Authorization: `Bearer ${pricingToken}` } }); if (!response.ok) throw new Error('دریافت تاریخچه پرداخت انجام نشد.'); const result = await response.json(); const payments = result.data?.data || []; paymentList.innerHTML = payments.length ? payments.map((payment) => `<div class="payment-row"><strong>${payment.plan_key}</strong><span>${money(payment.amount)}</span><span class="payment-status ${payment.status}">${paymentLabels[payment.status] || payment.status}</span><button class="text-button" data-payment-receipt="${payment.id}">رسید</button></div>`).join('') : '<p class="empty-state">هنوز پرداختی ثبت نشده است.</p>'; paymentList.querySelectorAll('[data-payment-receipt]').forEach((button) => button.addEventListener('click', async () => { button.disabled = true; const receipt = await fetch(`/api/payments/${button.dataset.paymentReceipt}/receipt`, { headers: { Accept: 'text/plain', Authorization: `Bearer ${pricingToken}` } }); if (receipt.ok) { const link = document.createElement('a'); link.href = URL.createObjectURL(await receipt.blob()); link.download = `payment-${button.dataset.paymentReceipt}-receipt.txt`; link.click(); } button.disabled = false; })); }; loadPayments().catch(() => { paymentList.innerHTML = '<p class="empty-state">تاریخچه پرداخت فعلاً در دسترس نیست.</p>'; }); fetch('/api/plans').then((response) => response.json()).then((result) => { pricingGrid.innerHTML = result.data.filter((plan) => plan.key !== 'free').map((plan) => `<article class="pricing-card ${plan.key === 'creator' ? 'featured-plan' : ''}"><span class="plan-label">${plan.name}</span><strong>${plan.monthly_credits}<small> Credit / ماه</small></strong><p>${plan.video_limit ? `${plan.video_limit} خروجی ویدئویی در ماه` : 'ساخت تصویر نامحدود'}</p><div class="plan-price">${money(plan.price_irr)}</div><button class="primary-button plan-button" data-plan="${plan.key}">انتخاب پلن <span>←</span></button></article>`).join(''); document.querySelectorAll('[data-plan]').forEach((button) => button.addEventListener('click', async () => { if (!pricingToken) { pricingMessage.className = 'form-message error-message'; pricingMessage.textContent = 'برای انتخاب پلن، ابتدا وارد حساب کاربری خود شوید.'; return; } button.disabled = true; button.textContent = 'در حال اتصال...'; const response = await fetch('/api/subscriptions/checkout', { method: 'POST', headers: { Accept: 'application/json', 'Content-Type': 'application/json', Authorization: `Bearer ${pricingToken}`, 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ plan_key: button.dataset.plan }) }); const checkout = await response.json(); if (response.ok) window.location.href = checkout.data.redirect_url; else { pricingMessage.textContent = response.status === 402 ? 'اعتبار یا پلن برای این پرداخت قابل استفاده نیست.' : (checkout.error?.message || 'Checkout انجام نشد.'); button.disabled = false; button.innerHTML = 'انتخاب پلن <span>←</span>'; } })); }).catch(() => { pricingMessage.textContent = 'دریافت پلن‌ها انجام نشد.'; });</script></body></html>
